package com.mlserver.inference;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.*;

public class ModelInferenceServer {

    private static final String UPLOAD_DIR = "/opt/mlserver/uploads/";
    private static final String MODEL_DIR = "/opt/mlserver/models/";
    private static final String SANDBOX_POLICY = "/opt/mlserver/sandbox.policy";
    private static final Set<String> ALLOWED_EXTENSIONS = Set.of(".onnx", ".pb", ".tflite");
    private final ExecutorService inferencePool = Executors.newFixedThreadPool(4);
    private final Map<String, ModelMetadata> registeredModels = new ConcurrentHashMap<>();

    public static class ModelMetadata {
        public final String modelId;
        public final String ownerUserId;
        public final Path modelPath;
        public final long uploadTimestamp;
        public final String checksum;

        public ModelMetadata(String modelId, String ownerUserId, Path modelPath, String checksum) {
            this.modelId = modelId;
            this.ownerUserId = ownerUserId;
            this.modelPath = modelPath;
            this.uploadTimestamp = System.currentTimeMillis();
            this.checksum = checksum;
        }
    }

    public String handleModelUpload(String userId, String filename, byte[] content) throws Exception {
        validateUser(userId);
        String sanitizedFilename = sanitizeFilename(filename);
        validateExtension(sanitizedFilename);
        validateModelSize(content);

        String modelId = generateModelId(userId, sanitizedFilename);
        Path targetPath = Paths.get(UPLOAD_DIR, userId, modelId, sanitizedFilename);
        Files.createDirectories(targetPath.getParent());
        Files.write(targetPath, content, StandardOpenOption.CREATE_NEW);

        String checksum = computeSHA256(content);
        ModelMetadata metadata = new ModelMetadata(modelId, userId, targetPath, checksum);
        registeredModels.put(modelId, metadata);

        return modelId;
    }

    public Object runInference(String userId, String modelId, byte[] inputData) throws Exception {
        validateUser(userId);
        ModelMetadata metadata = registeredModels.get(modelId);
        if (metadata == null) {
            throw new SecurityException("Model not found: " + modelId);
        }

        if (!metadata.ownerUserId.equals(userId) && !isSharedModel(modelId, userId)) {
            throw new SecurityException("Access denied to model: " + modelId);
        }

        return inferencePool.submit(() -> executeInference(metadata, inputData)).get(30, TimeUnit.SECONDS);
    }

    private Object executeInference(ModelMetadata metadata, byte[] inputData) throws Exception {
        ProcessBuilder pb = buildSandboxedProcess(metadata, inputData);
        Process process = pb.start();

        byte[] output = process.getInputStream().readAllBytes();
        int exitCode = process.waitFor();

        if (exitCode != 0) {
            byte[] errOutput = process.getErrorStream().readAllBytes();
            throw new RuntimeException("Inference failed: " + new String(errOutput));
        }

        return deserializeOutput(output);
    }

    private ProcessBuilder buildSandboxedProcess(ModelMetadata metadata, byte[] inputData) throws Exception {
        Path inputFile = writeTemporaryInput(inputData);
        Path modelPath = metadata.modelPath;

        List<String> command = new ArrayList<>();
        command.add("/usr/bin/java");
        command.add("-Djava.security.manager");
        command.add("-Djava.security.policy=" + SANDBOX_POLICY);
        command.add("-Xmx512m");
        command.add("-cp");
        command.add(getInferenceClasspath(metadata));
        command.add("com.mlserver.sandbox.InferenceRunner");
        command.add(modelPath.toString());
        command.add(inputFile.toString());

        ProcessBuilder pb = new ProcessBuilder(command);
        pb.environment().clear();
        pb.environment().put("JAVA_HOME", "/usr/lib/jvm/java-17");
        pb.environment().put("MODEL_OWNER", metadata.ownerUserId);
        pb.directory(new File(MODEL_DIR));

        return pb;
    }

    private String getInferenceClasspath(ModelMetadata metadata) {
        // Only include the trusted server libraries in classpath
        // Model files are passed as data arguments, never on classpath
        return "/opt/mlserver/lib/*";
    }

    private Path writeTemporaryInput(byte[] inputData) throws IOException {
        Path tempFile = Files.createTempFile("inference-input-", ".bin");
        Files.write(tempFile, inputData);
        tempFile.toFile().deleteOnExit();
        return tempFile;
    }

    private String sanitizeFilename(String filename) {
        String name = Paths.get(filename).getFileName().toString();
        name = name.replaceAll("[^a-zA-Z0-9._-]", "_");
        if (name.startsWith(".")) {
            name = "_" + name.substring(1);
        }
        return name;
    }

    private void validateExtension(String filename) {
        String lower = filename.toLowerCase();
        boolean valid = ALLOWED_EXTENSIONS.stream().anyMatch(lower::endsWith);
        if (!valid) {
            throw new SecurityException("Invalid file extension: " + filename);
        }
    }

    private void validateModelSize(byte[] content) {
        if (content.length > 100 * 1024 * 1024) {
            throw new SecurityException("Model exceeds maximum size of 100MB");
        }
    }

    private void validateUser(String userId) {
        if (userId == null || userId.isEmpty() || userId.length() > 64) {
            throw new SecurityException("Invalid user ID");
        }
        if (!userId.matches("[a-zA-Z0-9_-]+")) {
            throw new SecurityException("Invalid characters in user ID");
        }
    }

    private String generateModelId(String userId, String filename) {
        return userId + "-" + UUID.randomUUID().toString().substring(0, 8);
    }

    private String computeSHA256(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(data);
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private boolean isSharedModel(String modelId, String userId) {
        // Check sharing permissions in database
        return false;
    }

    private Object deserializeOutput(byte[] output) {
        // Parse inference output as simple float array
        if (output.length % 4 != 0) return output;
        float[] results = new float[output.length / 4];
        for (int i = 0; i < results.length; i++) {
            int bits = ((output[i*4] & 0xFF) << 24) | ((output[i*4+1] & 0xFF) << 16)
                     | ((output[i*4+2] & 0xFF) << 8) | (output[i*4+3] & 0xFF);
            results[i] = Float.intBitsToFloat(bits);
        }
        return results;
    }
}
